    public Object parseOrder(Object order, Map<String, Object> market)
    {
        //
        // createOrder - spot
        //     {
        //         "status": 2,
        //         "symbol": "ETH-USDT",
        //         "orderType": 76,
        //         "price": 1000,
        //         "side": "BUY",
        //         "orderID": "cde4fb37-2e2b-437e-a816-4b55b2e2b7c7",
        //         "timestamp": 1770813053751,
        //         "triggerPrice": 0,
        //         "stopPrice": null,
        //         "trigger": false,
        //         "message": "",
        //         "clOrderID": null,
        //         "stealth": 1,
        //         "deviation": 1,
        //         "postOnly": false,
        //         "orderDetailType": null,
        //         "originalOrderBaseSize": 0.0001,
        //         "originalOrderQuoteSize": null,
        //         "currentOrderBaseSize": 0.0001,
        //         "currentOrderQuoteSize": null,
        //         "remainingOrderBaseSize": 0.0001,
        //         "remainingOrderQuoteSize": null,
        //         "filledBaseSize": 0,
        //         "totalFilledBaseSize": 0,
        //         "orderCurrency": "base",
        //         "avgFilledPrice": 0,
        //         "time_in_force": "GTC"
        //     }
        //
        // createOrder - swap
        //     {
        //         "status": 4,
        //         "symbol": "ETH-PERP",
        //         "orderType": 77,
        //         "price": 1956.59,
        //         "side": "BUY",
        //         "orderID": "5c6a26db-8cfb-45c7-b25d-56927bc36795",
        //         "timestamp": 1770821231984,
        //         "triggerPrice": 0,
        //         "trigger": false,
        //         "deviation": 100,
        //         "stealth": 100,
        //         "message": "",
        //         "avgFilledPrice": 1956.59,
        //         "clOrderID": "",
        //         "originalOrderSize": 1,
        //         "currentOrderSize": 1,
        //         "filledSize": 1,
        //         "totalFilledSize": 1,
        //         "remainingSize": 0,
        //         "postOnly": false,
        //         "orderDetailType": null,
        //         "positionMode": "ONE_WAY",
        //         "positionDirection": null,
        //         "positionId": "ETH-PERP-USDT",
        //         "time_in_force": "GTC"
        //     }
        //
        String marketId = this.safeString2(order, "symbol", "market");
        Map<String, Object> marketResolved = this.safeMarket(marketId, market, (String) null, (String) null);
        Long timestamp = this.safeInteger(order, "timestamp");
        // open_orders rows carry no numeric status - the state lives in
        // orderState (STATUS_ACTIVE / STATUS_INACTIVE), and time_in_force
        // is spelled timeInForce there (observed live), so both fall back
        String rawStatus = this.safeString2(order, "status", "orderState");
        String rawType = this.safeString2(order, "orderType", "type");
        String status = this.parseOrderStatus(rawStatus);
        String orderType = this.parseOrderType(rawType);
        if ((java.util.Objects.equals(orderType, "market")) && (java.util.Objects.equals(status, "open")))
        {
            // market orders never rest on the book, the exchange reports the
            // partially filled code on them when a residual quote dust amount
            // cannot fill, observed live, such orders are finished
            status = "closed";
        }
        String rawTimeInForce = this.safeString2(order, "time_in_force", "timeInForce");
        return this.safeOrder(Helpers.newMap(
            "info", order,
            "id", this.safeString2(order, "orderID", "orderId"),
            "clientOrderId", this.safeString2(order, "clOrderID", "clOrderId"),
            "timestamp", timestamp,
            "datetime", this.iso8601(timestamp),
            "lastTradeTimestamp", null,
            "lastUpdateTimestamp", null,
            "status", status,
            "symbol", marketResolved.get("symbol"),
            "type", orderType,
            "timeInForce", this.parseTimeInForce(rawTimeInForce),
            "postOnly", this.safeBool(order, "postOnly", (Object) null),
            "reduceOnly", this.safeBool(order, "reduceOnly", (Object) null),
            "side", this.safeStringLower2(order, "side", "orderSide"),
            "price", this.safeString2(order, "price", "orderPrice"),
            "triggerPrice", this.omitZero(this.safeString2(order, "triggerOriginalPrice", "triggerPrice")),
            "stopLossPrice", null,
            "takeProfitPrice", null,
            "amount", this.safeStringN(order, new ArrayList<Object>(Arrays.asList("currentOrderBaseSize", "currentOrderSize", "orderSize"))),
            "filled", this.safeStringN(order, new ArrayList<Object>(Arrays.asList("totalFilledBaseSize", "totalFilledSize", "filledSize"))),
            "remaining", this.safeString2(order, "remainingOrderBaseSize", "remainingSize"),
            "cost", null,
            "trades", null,
            "fee", null,
            "average", this.omitZero(this.safeString2(order, "avgFilledPrice", "averageFillPrice"))
        ), marketResolved);
    }

    public String parseOrderStatus(String status)
    {
        Map<String, Object> statuses = new HashMap<String, Object>() {{
            put( "2", "open" );
            put( "3", "closed" );
            put( "4", "closed" );
            put( "5", "open" );
            put( "6", "canceled" );
            put( "7", "refunded" );
            put( "8", "rejected" );
            put( "9", "open" );
            put( "10", "open" );
            put( "15", "rejected" );
            put( "16", "rejected" );
            put( "17", "rejected" );
            put( "123", "open" );
            put( "STATUS_ACTIVE", "open" );
            put( "STATUS_INACTIVE", "canceled" );
            put( "ORDER_INSERTED", "open" );
            put( "ORDER_PARTIALLY_TRANSACTED", "open" );
            put( "ORDER_FULLY_TRANSACTED", "closed" );
            put( "ORDER_CANCELLED", "canceled" );
        }};
        return this.safeString(statuses, status, status);
    }

