        Map<String, Object> types = new HashMap<String, Object>() {{
            put( "Deposit", "deposit" );
            put( "Withdraw", "withdrawal" );
            put( "DEPOSIT", "deposit" );
            put( "WITHDRAW", "withdrawal" );
        }};
        return this.safeString(types, type, type);
